settings.cellContentFunction:
let valueLength = value.length;

function getFirst50Characters(inputString) {
    return inputString.substring(0, 50);
}

if(value && valueLength>50){

    return `<span title="${value}">
                ${getFirst50Characters(value)}...
            </span>`;
}
return value;

